  add(yl,"v"); add(y0,"v0"); const L=Object.values(rows).filter(r=>r.v||r.v0).sort((a,b)=>b.v-a.v); const T=L.reduce((a,r)=>a+r.v,0), T0=L.reduce((a,r)=>a+r.v0,0);
