  const sel=`<select onchange="location.hash='#/rynek/s:'+encodeURIComponent(this.value)">${(subs.includes(S)?subs:[S].concat(subs)).map(x=>`<option ${x===S?"selected":""} value="${esc(x)}">${esc(x)}</option>`).join("")}</select>`;
  const last=yrs[ly]||[null,null], prev=yrs[String(+ly-1)];
