   <div class="grid g4 strip">${[["Refundacja "+ly,last[1]==null?null:pln(last[1]),prev?`${+ly-1}: ${pln(prev[1])} (${A().pct(last[1]/prev[1]-1)})`:""],["Pacjenci "+ly,last[0]==null?null:nf(last[0]),prev?`${+ly-1}: ${nf(prev[0])} · suma po programach`:"suma po programach"],["Programy z tą substancją",nf(new Set(pRows.map(r=>r.p)).size),pRows.slice(0,3).map(r=>progLbl(r.p)).join(", ")],["Udział "+esc(c)+" w substancji ("+esc(yl)+")",(coRows.find(r=>r.mine)||{}).sh==null?null:shN(coRows.find(r=>r.mine).sh),"raport refundacyjny, kody EAN"]].map(([l,v,d])=>`<div class="card kpi"><div class="l">${l}</div><div class="v">${v==null?NDs:v}</div><div class="d">${d}</div></div>`).join("")}</div>
