// mobile: każda długa lista/tabela poza table() → 25 pozycji + „Pokaż więcej”
function clampMobile(app){const N=25; const go=(items,host)=>{if(items.length<=N) return; items.slice(N).forEach(e=>e.style.display="none"); const b=document.createElement("button"); b.className="btn cmore"; let shown=N;
    const upd=()=>{if(shown>=items.length){b.remove(); return;} b.textContent=`Pokaż więcej (${items.length-shown})`;}; b.onclick=()=>{items.slice(shown,shown+100).forEach(e=>e.style.display=""); shown+=100; upd();}; upd(); host.after(b);};
  app.querySelectorAll("table").forEach(t=>{const tb=t.tBodies[0]; if(!tb) return; const w=t.parentElement&&t.parentElement.parentElement; if(w&&w.querySelector(":scope > .more")) return; const rows=[...tb.rows]; if(rows.length>N) go(rows,t.closest(".tw,.tablewrap")||t);});
  app.querySelectorAll(".list").forEach(l=>{const rows=[...l.children]; if(rows.length>N) go(rows,l);});
  // strona nadal > ~14 tys. px → kolejne sekcje (od 2.) zwijane do nagłówka (od największych)
  if(document.documentElement.scrollHeight>14000){const cards=[...app.querySelectorAll(".card")].filter(cd=>!cd.closest("details")&&!cd.parentElement.closest(".card")&&cd.querySelector(":scope > h2"));
    cards.slice(1).sort((a,b)=>b.offsetHeight-a.offsetHeight).forEach(cd=>{if(document.documentElement.scrollHeight<=14000) return; const h=cd.querySelector(":scope > h2"); const d=document.createElement("details"); d.className="card mcol";
      d.innerHTML=`<summary><b>${h.innerHTML}</b> <span class="muted">(rozwiń)</span></summary>`; cd.before(d); h.remove(); cd.classList.add("inner"); d.appendChild(cd);});
    [...app.querySelectorAll(":scope > .grid")].filter(g=>g.previousElementSibling&&g.previousElementSibling.tagName==="H2"&&g.children.length>4).sort((a,b)=>b.offsetHeight-a.offsetHeight).forEach(g=>{if(document.documentElement.scrollHeight<=14000) return; const h=g.previousElementSibling; const d=document.createElement("details"); d.className="card mcol";
      d.innerHTML=`<summary><b>${h.innerHTML}</b> <span class="muted">(${g.children.length} – rozwiń)</span></summary>`; g.before(d); h.remove(); d.appendChild(g);});}}
function after(v,a){pill(); const app=document.getElementById("app"); if(!app) return;
  if(window.STRIPS&&!document.body.classList.contains("printing")) STRIPS.decorate(v,a);
  if(innerWidth<=600) setTimeout(()=>clampMobile(app),60);
  if(v==="przeglad"){const cards=[...app.querySelectorAll(":scope > .card, :scope > .grid, :scope > .alert")]; if(cards.length>3){const d=document.createElement("details"); d.className="more card"; d.innerHTML="<summary><b>Więcej danych przeglądu</b> <span class='muted'>(szczegóły, listy, alerty wzrostu NFZ)</span></summary>"; cards[2].before(d); cards.slice(2).forEach(x=>d.appendChild(x));}}
  if(v==="pacjenci"){app.querySelectorAll(".card").forEach(cd=>{const h=cd.querySelector("h2"); if(h&&/ICD|rozpozna/i.test(h.textContent)&&cd.querySelector("table")&&!cd.closest("details")){const d=document.createElement("details"); d.className="card"; d.innerHTML=`<summary><b>${h.textContent}</b> <span class="muted">(pełna tabela)</span></summary>`; cd.before(d); d.appendChild(cd); cd.classList.remove("card");}});}
  if(v==="dostep"){app.querySelectorAll("table tbody tr").forEach(tr=>{const t=tr.textContent; if(/poza wykazem/.test(t)&&!/\d/.test(t.replace(/B\.\d+|\d{4}-\d\d-\d\d/g,""))) tr.remove();});}
  labelTables(app);}
function labelTables(root){const go=()=>root.querySelectorAll("table").forEach(t=>{const hs=[...t.querySelectorAll("thead th")].map(th=>th.textContent.replace(/[▲▼↕]/g,"").trim()); t.querySelectorAll("tbody tr").forEach(tr=>[...tr.children].forEach((td,i)=>{if(!td.dataset.l&&hs[i]) td.dataset.l=hs[i];}));});
  go(); setTimeout(go,50); setTimeout(go,600); if(!labelTables.mo){labelTables.mo=new MutationObserver(()=>{clearTimeout(labelTables.t); labelTables.t=setTimeout(go,30);}); labelTables.mo.observe(root,{childList:true,subtree:true});}}
